steps.script:
const el = document.getElementById('__UNIVERSAL_DATA_FOR_REHYDRATION__');
if (!el) return { url: location.href, loi: 'Không đọc được dữ liệu trang' };
const d = JSON.parse(el.textContent).__DEFAULT_SCOPE__?.['webapp.video-detail']?.itemInfo?.itemStruct;
if (!d) return { url: location.href, loi: 'Không có dữ liệu video (video riêng tư hoặc bị chặn)' };
const s = d.statsV2 || d.stats || {};
return { url: location.href, tac_gia: d.author?.uniqueId, ten: d.author?.nickname, mo_ta: d.desc,
  ngay_dang: new Date(d.createTime * 1000).toLocaleString('vi-VN'), thoi_luong_giay: d.video?.duration,
  luot_xem: Number(s.playCount), like: Number(s.diggCount), comment: Number(s.commentCount),
  share: Number(s.shareCount), luu: Number(s.collectCount), nhac: d.music?.title };
